import AppKit
import CryptoKit
import Foundation

/// Pasteboard types that password managers and other apps use to mark content as secret or short-lived
/// (https://nspasteboard.org). Anything carrying one of them is never stored.
public enum PasteboardMarkers {
    public static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    public static func isMarkedPrivate(_ types: [String]) -> Bool {
        types.contains { skipTypes.contains($0) }
    }
}

/// What was on the pasteboard at one moment. Built by `PasteboardReader`, consumed by `HistoryCapture`.
public struct PasteboardSnapshot: Sendable {
    public var changeCount: Int
    public var types: [String]
    public var text: String?
    public var rtf: Data?
    /// PNG-encoded.
    public var image: Data?
    public var pdf: Data?
    public var fileURLs: [URL]
    public var sourceApp: String?

    public init(
        changeCount: Int = 0, types: [String] = [], text: String? = nil, rtf: Data? = nil,
        image: Data? = nil, pdf: Data? = nil, fileURLs: [URL] = [], sourceApp: String? = nil
    ) {
        self.changeCount = changeCount
        self.types = types
        self.text = text
        self.rtf = rtf
        self.image = image
        self.pdf = pdf
        self.fileURLs = fileURLs
        self.sourceApp = sourceApp
    }
}

public enum ScreeningResult: Equatable, Sendable {
    case clear(String)
    case sensitive([String])
    case unavailable(String)
}

/// Looks for secrets in images and PDFs. Implementations are best-effort and must run on this Mac only.
public protocol ContentScreener: Sendable {
    func screen(imagePNG: Data) -> ScreeningResult
    func screen(pdf: Data) -> ScreeningResult
}

public enum CaptureOutcome: Equatable, Sendable {
    case stored(UUID)
    case skipped(String)

    public var reason: String? {
        if case .skipped(let reason) = self { return reason }
        return nil
    }
}

public enum CaptureReasons {
    public static func label(_ reason: String) -> String {
        switch reason {
        case "marked-private": "Aplikace označila obsah jako soukromý nebo dočasný (např. správce hesel)"
        case "sensitive-content": "Text vypadá jako heslo, klíč nebo token"
        case "empty": "Prázdný obsah"
        case "too-large": "Položka je větší než nastavený limit"
        case "unsupported-format": "Formát, který historie neukládá"
        case "images-not-allowed": "Ukládání obrázků není povoleno"
        case "pdf-not-allowed": "Ukládání PDF není povoleno"
        case "screening-unavailable": "Obsah se nepodařilo bezpečně prověřit"
        case "sensitive-image": "Na obrázku nebo v PDF byl rozpoznán citlivý text"
        case "too-many-files": "Příliš mnoho souborů"
        case "store-failed": "Uložení selhalo"
        default: reason
        }
    }
}

/// Decides whether a pasteboard snapshot may enter the history, and in what form.
public struct HistoryCapture: Sendable {
    public static let maxPreviewCharacters = 280
    public static let maxSearchCharacters = 4_000
    public static let maxFileReferences = 500

    public let store: HistoryStore
    public let screener: any ContentScreener

    public init(store: HistoryStore, screener: any ContentScreener) {
        self.store = store
        self.screener = screener
    }

    /// Text is always scanned before it is written to disk, even when the global protection switch is off:
    /// a history file persists, a one-off copy does not.
    public func process(_ snapshot: PasteboardSnapshot, settings: ClipboardHistorySettings) -> CaptureOutcome {
        guard settings.isCapturing else { return .skipped("history-off") }
        if PasteboardMarkers.isMarkedPrivate(snapshot.types) { return .skipped("marked-private") }

        let candidate: Result<NewHistoryItem, Skip>
        if !snapshot.fileURLs.isEmpty {
            candidate = files(snapshot)
        } else if let text = snapshot.text ?? Self.plainText(fromRTF: snapshot.rtf), !text.isEmpty || snapshot.rtf != nil {
            candidate = textItem(text, snapshot: snapshot, settings: settings)
        } else if let pdf = snapshot.pdf {
            candidate = pdfItem(pdf, snapshot: snapshot, settings: settings)
        } else if let image = snapshot.image {
            candidate = imageItem(image, snapshot: snapshot, settings: settings)
        } else {
            candidate = .failure(Skip("unsupported-format"))
        }

        switch candidate {
        case .failure(let skip): return .skipped(skip.reason)
        case .success(let new):
            guard new.byteSize <= settings.maxItemBytes else { return .skipped("too-large") }
            do {
                return .stored(try store.add(new, settings: settings).id)
            } catch {
                return .skipped("store-failed")
            }
        }
    }

    struct Skip: Error { var reason: String; init(_ reason: String) { self.reason = reason } }

    private func textItem(_ text: String, snapshot: PasteboardSnapshot, settings: ClipboardHistorySettings) -> Result<NewHistoryItem, Skip> {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return .failure(Skip("empty")) }
        let payload = Data(text.utf8)
        // Only the plain text is checked against the byte limit up front; RTF is checked as part of the item.
        guard payload.count <= min(settings.maxItemBytes, 1_048_576) else { return .failure(Skip("too-large")) }
        guard SensitiveDataScanner.scan(text).isEmpty else { return .failure(Skip("sensitive-content")) }

        var blobs = ["text": payload]
        var kind = HistoryKind.text
        var hashInput = payload
        if let rtf = snapshot.rtf, rtf.count <= settings.maxItemBytes {
            blobs["rtf"] = rtf
            kind = .richText
            hashInput.append(rtf)
        }
        return .success(NewHistoryItem(
            kind: kind, preview: Self.preview(of: trimmed), searchText: Self.searchText(of: trimmed),
            contentHash: Self.sha256(hashInput), sourceApp: snapshot.sourceApp, blobs: blobs, files: nil,
            screening: "text-scan"
        ))
    }

    private func files(_ snapshot: PasteboardSnapshot) -> Result<NewHistoryItem, Skip> {
        let urls = snapshot.fileURLs.filter(\.isFileURL)
        guard !urls.isEmpty else { return .failure(Skip("unsupported-format")) }
        guard urls.count <= Self.maxFileReferences else { return .failure(Skip("too-many-files")) }
        let refs = urls.map { url -> HistoryFileRef in
            var isDirectory: ObjCBool = false
            FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)
            return HistoryFileRef(
                path: url.path, name: url.lastPathComponent, isDirectory: isDirectory.boolValue,
                bookmark: try? url.bookmarkData(options: [], includingResourceValuesForKeys: nil, relativeTo: nil)
            )
        }
        // File names can carry secrets too (e.g. "token=…").
        guard SensitiveDataScanner.scan(refs.map(\.path).joined(separator: "\n")).isEmpty else {
            return .failure(Skip("sensitive-content"))
        }
        let names = refs.map(\.name)
        let preview = names.count == 1 ? names[0] : "\(names.count) položek: " + names.prefix(3).joined(separator: ", ") + (names.count > 3 ? "…" : "")
        return .success(NewHistoryItem(
            kind: .files, preview: Self.preview(of: preview), searchText: Self.searchText(of: refs.map(\.path).joined(separator: " ")),
            contentHash: Self.sha256(Data(refs.map(\.path).joined(separator: "\n").utf8)), sourceApp: snapshot.sourceApp,
            blobs: [:], files: refs, screening: "references-only"
        ))
    }

    private func imageItem(_ png: Data, snapshot: PasteboardSnapshot, settings: ClipboardHistorySettings) -> Result<NewHistoryItem, Skip> {
        guard settings.storeImages else { return .failure(Skip("images-not-allowed")) }
        guard png.count <= settings.maxItemBytes else { return .failure(Skip("too-large")) }
        switch screener.screen(imagePNG: png) {
        case .sensitive: return .failure(Skip("sensitive-image"))
        case .unavailable: return .failure(Skip("screening-unavailable"))
        case .clear(let note):
            let size = NSBitmapImageRep(data: png).map { "\($0.pixelsWide) × \($0.pixelsHigh) px" } ?? "obrázek"
            return .success(NewHistoryItem(
                kind: .image, preview: "Obrázek \(size)", searchText: "", contentHash: Self.sha256(png),
                sourceApp: snapshot.sourceApp, blobs: ["image": png], files: nil, screening: note
            ))
        }
    }

    private func pdfItem(_ pdf: Data, snapshot: PasteboardSnapshot, settings: ClipboardHistorySettings) -> Result<NewHistoryItem, Skip> {
        guard settings.storePDF else { return .failure(Skip("pdf-not-allowed")) }
        guard pdf.count <= settings.maxItemBytes else { return .failure(Skip("too-large")) }
        switch screener.screen(pdf: pdf) {
        case .sensitive: return .failure(Skip("sensitive-image"))
        case .unavailable: return .failure(Skip("screening-unavailable"))
        case .clear(let note):
            return .success(NewHistoryItem(
                kind: .pdf, preview: "Dokument PDF", searchText: "", contentHash: Self.sha256(pdf),
                sourceApp: snapshot.sourceApp, blobs: ["pdf": pdf], files: nil, screening: note
            ))
        }
    }

    // MARK: Helpers

    static func preview(of text: String) -> String {
        let flat = text.split(whereSeparator: \.isNewline).joined(separator: " ")
        return flat.count > maxPreviewCharacters ? String(flat.prefix(maxPreviewCharacters)) + "…" : flat
    }

    static func searchText(of text: String) -> String {
        HistorySearch.fold(String(text.prefix(maxSearchCharacters)))
    }

    static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    static func plainText(fromRTF rtf: Data?) -> String? {
        guard let rtf, let attributed = try? NSAttributedString(
            data: rtf, options: [.documentType: NSAttributedString.DocumentType.rtf], documentAttributes: nil
        ) else { return nil }
        return attributed.string
    }
}
